    for (const s of [-1, 1]) wb(S, 'A', u + s * 0.23 - 0.012, u + s * 0.23 + 0.012, 0.12, FB0, 0.13, 0.142, { all: [RW, BRASS, MM.brass], skip: 'nz ny py' });
