  for (const y of [FB0 + 0.01, FB1 - 0.01]) wb(S, 'A', -ZS, ZS, y - 0.012, y + 0.012, 0.2, 0.207, { pz: [RW, BRASS, MM.brass], py: [RW, BRASS, MM.brass], ny: [RW, BRASS, MM.brass] });
