      for (const [lx, pos] of [[-0.13, 'tens'], [0.13, 'ones']]) digits.push({ ...lq(Dg.p(lx - 0.11, -0.17, 0.105), Dg.p(lx + 0.11, -0.17, 0.105), Dg.p(lx + 0.11, 0.17, 0.105), Dg.p(lx - 0.11, 0.17, 0.105), subUV(PU.digits, 0, 0, 0.1, 1), 'D', group), pos });
