        lamps.push(lq(Ph.p(-0.13, -0.28, 0.105), Ph.p(0.13, -0.28, 0.105), Ph.p(0.13, -0.02, 0.105), Ph.p(-0.13, -0.02, 0.105), PU.pedG, 'pG', pg));
