    const bins = [[-233.5, 4.9, '#2f7a4c'], [-229.6, -5.0, '#2f6fb0'], [-296.3, 4.9, '#2f7a4c'], [-257.4, -4.9, '#2f6fb0'], [-187.3, -4.9, '#2f7a4c'], [-343.2, 5.4, '#2f6fb0']];
