  for (let i = 0; i < prof.length; i++) { const a = prof[i], b = prof[(i + 1) % prof.length]; q([a[0], a[1], hz], [a[0], a[1], -hz], [b[0], b[1], -hz], [b[0], b[1], hz], edgeUV[i]); }
