  for (const x of [-383.8, -380.2, -376.6]) line(x, 12.2, x, 17.8); line(-383.8, 12.2, -376.6, 12.2); // 警車的停車格
  for (const x of [-362.3, -358.7, -355.1]) line(x, 12.2, x, 17.8); line(-362.3, 12.2, -355.1, 12.2); // 訪客（你的車被拖來也停這裡）
