  box(m, T, [-10.2, 0, Z0, -10.1, 1.2, Z0 + 1.2], C('#d9d7d1')); box(m, T, [-9.9, 0, Z0 + 0.2, -9.3, 0.4, Z0 + 0.8], C('#f2f3f5')); cl(-10.2, Z0, -9.2, Z0 + 1.2, 1.2); // 廁所（矮牆）
