      B.quad('main', T.p(-w / 2 + 0.05, H + 3.2, -D + 4.0), T.p(w / 2 - 0.05, H + 3.2, -D + 4.0), T.p(w / 2 - 0.05, H + 2.62, z1 + 0.4), T.p(-w / 2 + 0.05, H + 2.62, z1 + 0.4), WD, mul(rc, 0.5));
