      for (const [a, b, c] of [[y0, Math.min(y1, 5), wall1], [Math.max(y0, 5), y1, wall2]]) if (b - a > 0.01) box('main', T, [x0, a, z0, x1, b, z1], { [out]: c, [IN[out]]: inner, _: mix(c, inner, 0.5) }, { _: U.corr });
