    const j = (i + 1) % nd, ax = D[i][0], az = D[i][1], dx = D[j][0] - ax, dz = D[j][1] - az, l2 = dx * dx + dz * dz, t = clamp(((150 - ax) * dx + (90 - az) * dz) / l2, 0, 1);
