    let spread = 0; for (const [ri, e] of N.ent) { const r = N.roads[ri], ni = r.n[e ? r.n.length - 1 : 0]; spread = Math.max(spread, Math.abs((nx(ni) - E[0]) * -d[1] + (nz(ni) - E[1]) * d[0]) + r.w / 2); }
    const wEnd = Math.max(13, spread * 2 + 1), nT = pts.length - 1 - nS;
