    const lx = x - AX, lz = z - AZ, n = Math.sin(lx * 0.0061 + 1.3) * 0.5 + Math.sin(lx * 0.013 + lz * 0.007) * 0.3 + Math.sin(lz * 0.011 - lx * 0.004 + 2) * 0.2; // −1…1
    const rise = (d, H, k) => H * (1 - Math.exp(-Math.max(0, d - HM) / k));
