    const y0 = 8.6, yg = 15.2, P = [[x - ux * hl - vx * hw, z - uz * hl - vz * hw], [x + ux * hl - vx * hw, z + uz * hl - vz * hw], [x + ux * hl + vx * hw, z + uz * hl + vz * hw], [x - ux * hl + vx * hw, z - uz * hl + vz * hw]];
