    quad3(g, [[P[3][0], y0 + 0.5, P[3][1]], [P[2][0], y0 + 0.5, P[2][1]], [P[1][0], y0 + 0.5, P[1][1]], [P[0][0], y0 + 0.5, P[0][1]]], [[0, 0], [0, hl / 3], [hw / 3, hl / 3], [hw / 3, 0]], 18, [222, 216, 202]); // 月台地板（米色磁磚）
