      for (let i = 0; i < 4; i++) { const a = Q[i], c = Q[(i + 1) % 4], L = Math.hypot(c[0] - a[0], c[1] - a[1]); wallQ(g, a[0], a[1], c[0], c[1], y1a, y2a, 0, L / 6, 0, 1, cell, cc); }
