      for (let i = 0; i < P.length; i += 2) { const a = grow(P, -8)[i]; strip('walk', [a, [(a[0] + c[0]) / 2, (a[1] + c[1]) / 2], c], 2.6, 0.05, [206, 204, 198], 2, TG); } // 幾條往中間的
