const armOff = (M, sd, phi, f, off, o) => { const J = M.shJ[sd < 0 ? 0 : 1]; return offPt((m, a, b, oo) => armPt(m, sd, a, b, oo), M, phi, f, 0.02, 0.01, off, J[0], J[1] - f * (M.upper + M.fore) - (f < 0 ? 0.02 : 0), J[2] + sd * 0.004, o); };
