    stitch(P, [[X(4) - 2, rowY(r, 0.1)], [X(4) - 2, rowY(r, 0.75)], [X(10) + 2, rowY(r, 0.75)], [X(10) + 2, rowY(r, 0.1)]], { k: 0.7, a: 0.5, seg: 1.4, gap: 1 });
