const CH = ['hx', 'hy', 'hz', 'hp', 'hr', 'hw', 'sp', 'sr', 'sw', 'cp', 'cr', 'cw', 'np', 'nr', 'nw', 'kp', 'kr', 'kw', 'tail'];
