  wheels: { xf: 1.21, xr: -1.441, RF: 0.3335, RR: 0.370, rimF: 0.262, rimR: 0.275, trackF: 0.8455, trackR: 0.8155, wF: 0.265, wR: 0.345, style: SP3_spokes },
