    const d = dx * ax + dz * az;
    const o = hl * Math.abs(fx * ax + fz * az) + hw * Math.abs(rx * ax + rz * az) + c.hx * Math.abs(c.ux * ax + c.uz * az) + c.hz * Math.abs(c.wx * ax + c.wz * az) - Math.abs(d);
    if (o <= 0) return false;
    if (o < best) { best = o; const s = d < 0 ? -1 : 1; nx = ax * s; nz = az * s; }
