    const rot = c0.rot || 0, c = { box, x: c0.x, z: c0.z, hx: box ? c0.hx : 0, hz: box ? c0.hz : 0, r: box ? 0 : c0.r, h: c0.h ?? 9, ux: Math.cos(rot), uz: -Math.sin(rot), wx: Math.sin(rot), wz: Math.cos(rot), s: 0 };
