    crimes.push({ t: +T0.toFixed(2), type, x: +x.toFixed(1), z: +z.toFixed(1), stars: wanted }); if (crimes.length > 40) crimes.shift();
    lastX = x; lastZ = z; heat = 0; dropped = false;
