    const g = new THREE.BoxGeometry(x1 - x0, 0.9, 0.4), uv = g.attributes.uv; for (let i = 0; i < uv.count; i++) uv.setX(i, (uv.getX(i) * (x1 - x0)) / LEN); // 貼圖照長度（短的不要擠）
